UPDATE USPM_PORT
   SET TT        = #{tt}
     , INST_DAYS = #{instDays}
     , MANGI     = TO_DATE(#{mangiYmd}, 'YYYY-MM-DD')
     , DT        = #{dt}
     , CALL_Z    = #{z}
 WHERE CORP_GR   = #{corpGr}
   AND TYMD      = TO_DATE(#{tymd}, 'YYYY-MM-DD')
   AND FUND_CD   = #{fundCd}
   AND PORT_NUM  = #{portNum}

UPDATE USPM
   SET TARGET_RETURN_PER = #{targetReturnPer}
 WHERE CORP_GR           = #{corpGr}
   AND YMD               = TO_DATE(#{ymd}, 'YYYY-MM-DD')
   AND FUND_CD           = #{fundCd}
   AND PORT_NUM          = #{portNum}
   AND JM_CD             = #{yjCd}

