SELECT NVL(MAX(TR_SEQ), 0) + 1
  FROM SYT1MG t1
 WHERE t1.CORP_GR = #{corpGr}
   AND t1.TR_YMD  = #{ymd}
   AND t1.FUND_CD = #{fundCd}
   AND t1.JM_CD   = #{jmCd}
   AND t1.TR_CD   = #{trCd}

